import"./style.a87c9e06.js";async function r(){const a=await miro.board.createStickyNote({content:"Hello, World!"});await miro.board.viewport.zoomTo(a)}r();async function c(a){return new Promise(o=>{const t=new Image;t.onload=()=>{const e=document.createElement("canvas");e.width=t.width,e.height=t.height;const i=e.getContext("2d");i.translate(e.width,0),i.scale(-1,1),i.drawImage(t,0,0);const n=e.toDataURL("image/png");o(n)},t.src=a})}async function s(a){return new Promise(o=>{const t=new Image;t.onload=()=>{const e=document.createElement("canvas");e.width=t.width,e.height=t.height;const i=e.getContext("2d");i.translate(0,e.height),i.scale(1,-1),i.drawImage(t,0,0);const n=e.toDataURL("image/png");o(n)},t.src=a})}async function l(){try{const o=(await miro.board.getSelection()).filter(t=>t.type==="image");if(o.length===0){await miro.board.notifications.showInfo("Please select at least one image to flip");return}for(const t of o){const e=await t.getDataUrl(),i=await c(e);await miro.board.createImage({title:"Flipped Image",url:i,x:t.x+100,y:t.y,width:t.width})}}catch(a){console.error("Error flipping image:",a),await miro.board.notifications.showError("Error flipping image")}}async function m(){try{const o=(await miro.board.getSelection()).filter(t=>t.type==="image");if(o.length===0){await miro.board.notifications.showInfo("Please select at least one image to flip");return}for(const t of o){const e=await t.getDataUrl(),i=await s(e);await miro.board.createImage({title:"Flipped Image",url:i,x:t.x,y:t.y+100,width:t.width})}}catch(a){console.error("Error flipping image:",a),await miro.board.notifications.showError("Error flipping image")}}async function g(){const a=document.querySelector("button:first-of-type"),o=document.querySelector("button:last-of-type");a.addEventListener("click",l),o.addEventListener("click",m)}g();
